QuestsSorted.NameClass:
if (Quest.HasQuest(12237) && !Quest.IsObjectiveComplete(1, 12237))
{
    wManager.wManagerSetting.CurrentSetting.UseMount = false;
    for (int a = 0; a < 6 && !ObjectManager.Me.InTransport && robotManager.Products.Products.IsStarted; a++)
    {
        WoWUnit g = null;
        foreach (var u in ObjectManager.GetObjectWoWUnit())
        {
            if (u.Entry == 27258 && !u.IsDead && u.GetDistance < 80) { g = u; break; }
        }
        if (g == null)
        {
            MovementManager.StopMove();
            Lua.LuaDoString("if IsMounted() then Dismount() end");
            ItemsManager.UseItem(37287);
            Thread.Sleep(600);
            Usefuls.WaitIsCasting();
            Thread.Sleep(3000);
            continue;
        }
        if (g.GetDistance > 4f) wManager.Wow.Bot.Tasks.GoToTask.ToPositionAndIntecractWithNpc(g.Position, 27258);
        ObjectManager.Me.Target = g.Guid;
        Thread.Sleep(300);
        Interact.InteractGameObject(g.GetBaseAddress);
        Thread.Sleep(2500);
        if (!ObjectManager.Me.InTransport) Lua.LuaDoString("if GossipFrame and GossipFrame:IsVisible() then GossipTitleButton1:Click() end");
        Thread.Sleep(1500);
    }

    System.Func<int> got = () => Lua.LuaDoString<int>("local n=0 for i=1,GetNumQuestLogEntries() do local _,_,_,h,_,_,_,id=GetQuestLogTitle(i) if not h and id==12237 then local t=GetQuestLogLeaderBoard(1,i) n=tonumber(string.match(t or '','(%d+)/')) or 0 end end return n");
    var station = new Vector3(3704f, -701f, 216f);
    var patrol = new Vector3[] { new Vector3(3699f, -1026f, 131f), new Vector3(3675f, -1045f, 133f), new Vector3(3734f, -1024f, 123f), new Vector3(3691f, -1138f, 123f), new Vector3(3650f, -1121f, 121f), new Vector3(3698f, -1238f, 117f), new Vector3(3785f, -1261f, 136f) };
    var used = new List<ulong>();
    Vector3 lastGo = new Vector3(0f, 0f, 0f);
    System.Action<Vector3> fly = (t) => { if (lastGo.DistanceTo(t) > 6f || !MovementManager.InMovement) { MovementManager.Go(new List<Vector3> { t }); lastGo = t; } };
    float cruise = 262f;
    var stop = System.DateTime.Now.AddMinutes(12);
    bool carrying = false;
    int pi = 0, nearTries = 0, dropTries = 0;
    int score = got();
    robotManager.Helpful.Logging.WriteDebug("[Flight] start, rescued=" + score);
    while (robotManager.Products.Products.IsStarted && ObjectManager.Me.InTransport && System.DateTime.Now < stop && Quest.HasQuest(12237) && !Quest.IsObjectiveComplete(1, 12237))
    {
        var mp = ObjectManager.Me.Position;
        int now = got();
        if (now > score) { score = now; carrying = false; dropTries = 0; robotManager.Helpful.Logging.WriteDebug("[Flight] rescued=" + score); }
        if (carrying)
        {
            float d = mp.DistanceTo(station);
            if (d > 14f) { fly(mp.DistanceTo2D(station) > 25f ? new Vector3(station.X, station.Y, cruise) : station); }
            else
            {
                MovementManager.StopMove();
                Lua.LuaDoString("VehicleMenuBarActionButton2:Click()");
                robotManager.Helpful.Logging.WriteDebug("[Flight] drop off");
                Thread.Sleep(1500);
                if (++dropTries >= 3) { carrying = false; dropTries = 0; }
            }
            Thread.Sleep(400);
            continue;
        }
        WoWUnit v = null; float vd = 99999f;
        foreach (var u in ObjectManager.GetObjectWoWUnit())
        {
            bool isV = u.Entry == 27315 || u.Entry == 27336 || u.Entry == 27345 || (u.Name != null && u.Name.Contains("Helpless Wintergarde Villager"));
            if (isV && !u.IsDead && !used.Contains(u.Guid) && u.GetDistance < vd) { vd = u.GetDistance; v = u; }
        }
        if (v == null)
        {
            var p = patrol[pi % patrol.Length];
            if (mp.DistanceTo2D(p) < 30f) pi++;
            fly(new Vector3(p.X, p.Y, cruise));
            Thread.Sleep(500);
            continue;
        }
        var vp = v.Position;
        float hd = mp.DistanceTo2D(vp);
        if (hd > 6f || System.Math.Abs(mp.Z - vp.Z) > 9f) { nearTries = 0; fly(hd > 25f ? new Vector3(vp.X, vp.Y, cruise) : new Vector3(vp.X, vp.Y, vp.Z + 4f)); Thread.Sleep(350); continue; }
        MovementManager.StopMove();
        ObjectManager.Me.Target = v.Guid;
        Lua.LuaDoString("VehicleMenuBarActionButton1:Click()");
        robotManager.Helpful.Logging.WriteDebug("[Flight] pickup try " + (nearTries + 1) + " villager " + v.Entry + " dist " + vd);
        Thread.Sleep(1800);
        if (++nearTries >= 2) { used.Add(v.Guid); nearTries = 0; carrying = true; }
    }
    if (ObjectManager.Me.InTransport)
    {
        var until = System.DateTime.Now.AddSeconds(45);
        while (robotManager.Products.Products.IsStarted && ObjectManager.Me.InTransport && System.DateTime.Now < until && ObjectManager.Me.Position.DistanceTo(station) > 14f)
        {
            fly(ObjectManager.Me.Position.DistanceTo2D(station) > 25f ? new Vector3(station.X, station.Y, cruise) : station);
            Thread.Sleep(400);
        }
        MovementManager.StopMove();
        Lua.LuaDoString("VehicleMenuBarActionButton2:Click()");
        Thread.Sleep(1000);
        Lua.LuaDoString("VehicleExit()");
        Thread.Sleep(2500);
    }
}

